// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.audio/** * NOUS — Noise Suppressor (RNNoise-style). * * Suppresses background noise (fans, traffic, keyboards, wind) from mic input * while preserving speech intelligibility. Uses a spectral-subtraction approach * inspired by RNNoise but implemented in pure Kotlin (no TFLite dependency). * * ## Algorithm (Spectral Subtraction with NN-style noise estimation) * *   1. Compute per-band energy (using DFT, same as VAD) *   2. Estimate noise floor per band (when no voice is detected) *   3. Compute per-band gain = max(1 - noiseFloor / signalEnergy, minGain) *   4. Apply gain to DFT magnitudes *   5. Reconstruct time-domain signal via inverse DFT * * This is a simplification of RNNoise (which uses a small RNN to estimate the * ideal mask). The pure-Kotlin version is suitable for devices without NNAPI * or as a fallback when the TFLite model is unavailable. When TFLite + the * RNNoise model are available, [TfLiteNoiseSuppressor] should be used instead * (better quality, ~5 dB SNR improvement vs ~3 dB for spectral subtraction). * * ## Performance * *   - Per chunk: ~0.5 ms (320 samples, 6 bands, DFT + iDFT) *   - Allocations: minimal (reuses internal buffers) *   - Suitable for real-time use on the audio capture thread * * ## Quality * *   - SNR improvement: ~3 dB (modest, but better than nothing) *   - Speech distortion: minimal (gain is applied to magnitudes only, *     preserving phase) *   - Musical noise: reduced by smoothing gains over time * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 Audio Capture Pipeline</a> */class NoiseSuppressor(    /** Minimum gain per band (0.0 = full suppression, 1.0 = no suppression). */    private val minGain: Float = DEFAULT_MIN_GAIN,    /** Smoothing factor for gain EMA (0.0 = no smoothing, 1.0 = instant). */    private val gainSmoothing: Float = DEFAULT_GAIN_SMOOTHING,    /** VAD used to detect speech (for noise floor update gating). */    private val vad: VoiceActivityDetector = VoiceActivityDetector(),    /** Initial noise floor in dBFS per band. */    initialNoiseFloorDb: Float = DEFAULT_NOISE_FLOOR_DB,) {    /** Per-band noise floor estimate (dBFS). */    private val noiseFloorDb: FloatArray = FloatArray(VoiceActivityDetector.NUM_BANDS) { initialNoiseFloorDb }    /** Per-band smoothed gain (0.0-1.0). */    private val smoothedGain: FloatArray = FloatArray(VoiceActivityDetector.NUM_BANDS) { 1.0f }    /** Whether this suppressor has been released. */    private var released: Boolean = false    /** Total chunks processed (for diagnostics). */    private var chunksProcessed: Long = 0L    /**     * Suppress noise from an audio chunk.     *     * @param chunk the input chunk (16 kHz, 16-bit, mono, 20 ms)     * @return a new chunk with noise suppressed     */    fun suppress(chunk: AudioChunk): AudioChunk {        check(!released) { "Cannot suppress after release" }        require(chunk.format.sampleRateHz == 16_000) {            "NoiseSuppressor requires 16 kHz audio, got ${chunk.format.sampleRateHz}"        }        require(chunk.sampleCount == AudioFormat.VOICE_16K.samplesPerFrame) {            "Chunk size ${chunk.sampleCount} doesn't match frame size ${AudioFormat.VOICE_16K.samplesPerFrame}"        }        chunksProcessed++        // Run VAD to determine if this chunk has voice (don't update noise floor if voice)        val vadResult = vad.detect(chunk)        // Compute DFT magnitudes (one-sided spectrum)        val n = chunk.sampleCount        val halfN = n / 2        ensureTwiddleTables(n)        val normalized = FloatArray(n) { chunk.samples[it].toFloat() / Short.MAX_VALUE }        val realParts = DoubleArray(halfN)        val imagParts = DoubleArray(halfN)        val mags = DoubleArray(halfN)        for (k in 0 until halfN) {            var real = 0.0            var imag = 0.0            for (i in 0 until n) {                val idx = (k * i) % n                real += normalized[i] * cosTable[idx]                imag -= normalized[i] * sinTable[idx]            }            realParts[k] = real            imagParts[k] = imag            mags[k] = kotlin.math.sqrt(real * real + imag * imag)        }        // Compute per-band energies (dBFS) and update noise floor        val binsPerBand = halfN / VoiceActivityDetector.NUM_BANDS        val bandGains = FloatArray(VoiceActivityDetector.NUM_BANDS)        for (band in 0 until VoiceActivityDetector.NUM_BANDS) {            val start = band * binsPerBand            val end = if (band == VoiceActivityDetector.NUM_BANDS - 1) halfN else start + binsPerBand            // Compute band energy in dBFS            var sumMagSq = 0.0            for (k in start until end) {                val weight = if (k == 0 || k == halfN) 1.0 else 2.0                sumMagSq += weight * mags[k] * mags[k]            }            val rms = if (end > start) kotlin.math.sqrt(sumMagSq) / n else 0.0            val bandEnergyDb = if (rms > 1e-10) (20.0 * kotlin.math.log10(rms)) else -120.0            // Update noise floor (only on silence)            if (!vadResult.isVoice) {                noiseFloorDb[band] = (noiseFloorDb[band] * (1f - NOISE_FLOOR_SMOOTHING)) +                    (bandEnergyDb.toFloat() * NOISE_FLOOR_SMOOTHING)            }            // Compute target gain: 1 - 10^((noiseFloor - signal) / 20)            // If signal >> noise → gain ≈ 1 (no suppression)            // If signal ≈ noise → gain ≈ 0 (full suppression)            val snrDb = bandEnergyDb - noiseFloorDb[band]            val targetGain = if (snrDb > 20) {                1.0f            } else if (snrDb < 0) {                minGain            } else {                // Linear interpolation in dB domain                val linear = (snrDb / 20.0).toFloat()                minGain + (1.0f - minGain) * linear            }            // Smooth gain over time (avoid musical noise artifacts)            smoothedGain[band] = (smoothedGain[band] * (1f - gainSmoothing)) +                (targetGain * gainSmoothing)            bandGains[band] = smoothedGain[band]        }        // Apply per-band gains to DFT magnitudes (preserve phase)        val newMags = DoubleArray(halfN)        for (band in 0 until VoiceActivityDetector.NUM_BANDS) {            val start = band * binsPerBand            val end = if (band == VoiceActivityDetector.NUM_BANDS - 1) halfN else start + binsPerBand            val gain = bandGains[band]            for (k in start until end) {                newMags[k] = mags[k] * gain            }        }        // Reconstruct time-domain signal via inverse DFT        // x[n] = (1/N) × Σ X[k] × exp(2πi kn/N)        val outputSamples = ShortArray(n)        for (i in 0 until n) {            var sum = 0.0            for (k in 0 until halfN) {                val idx = (k * i) % n                // Reconstruct complex DFT (X[k] = real + i*imag)                // Apply gain to magnitude while preserving phase                val origMag = mags[k]                val scaledReal: Double                val scaledImag: Double                if (origMag > 1e-10) {                    val gainFactor = newMags[k] / origMag                    scaledReal = realParts[k] * gainFactor                    scaledImag = imagParts[k] * gainFactor                } else {                    scaledReal = 0.0                    scaledImag = 0.0                }                // Inverse DFT: cos for real, sin (positive) for imag                // x[n] = (1/N) × Σ (real[k] * cos(2π kn/N) - imag[k] * sin(2π kn/N))                // Note: our sin table was computed for -2π, so sin table value                // is sin(-2π i/N) = -sin(2π i/N). We need to add imag*sin(2π),                // which means subtract imag * sinTable.                sum += scaledReal * cosTable[idx] - scaledImag * (-sinTable[idx])            }            // For real signal, sum negative-frequency contributions by doubling            // (already done via magnitude doubling in forward DFT).            // Final normalization: divide by N, multiply by 2 for one-sided spectrum.            val output = (sum * 2.0 / n * Short.MAX_VALUE)                .toInt()                .coerceIn(Short.MIN_VALUE.toInt(), Short.MAX_VALUE.toInt())                .toShort()            outputSamples[i] = output        }        return chunk.withSamples(outputSamples)    }    /** Get current noise floor estimate (snapshot, for diagnostics). */    fun getNoiseFloorDb(): FloatArray = noiseFloorDb.copyOf()    /** Get current smoothed gains (snapshot, for diagnostics). */    fun getGains(): FloatArray = smoothedGain.copyOf()    /** Number of chunks processed so far. */    fun getChunksProcessed(): Long = chunksProcessed    /** Reset state (noise floor, gains). */    fun reset() {        for (i in noiseFloorDb.indices) noiseFloorDb[i] = DEFAULT_NOISE_FLOOR_DB        for (i in smoothedGain.indices) smoothedGain[i] = 1.0f        vad.reset()        chunksProcessed = 0L    }    /** Release resources. */    fun release() {        if (released) return        released = true        vad.reset()    }    /** Precomputed cosine table for DFT (shared with VAD pattern). */    private var cosTable: FloatArray = FloatArray(0)    private var sinTable: FloatArray = FloatArray(0)    private var twiddleN: Int = 0    private fun ensureTwiddleTables(n: Int) {        if (twiddleN == n && cosTable.size == n) return        twiddleN = n        cosTable = FloatArray(n)        sinTable = FloatArray(n)        for (i in 0 until n) {            val angle = -2.0 * Math.PI * i / n            cosTable[i] = kotlin.math.cos(angle).toFloat()            sinTable[i] = kotlin.math.sin(angle).toFloat()        }    }    companion object {        /** Default minimum gain per band (suppress to 10% of original). */        const val DEFAULT_MIN_GAIN = 0.1f        /** Default gain smoothing factor. */        const val DEFAULT_GAIN_SMOOTHING = 0.3f        /** Noise floor EMA smoothing factor. */        const val NOISE_FLOOR_SMOOTHING = 0.05f        /** Default noise floor in dBFS. */        const val DEFAULT_NOISE_FLOOR_DB = -50f    }    protected fun finalize() {        release()    }}/** * NOUS — Automatic Gain Controller (AGC). * * Normalizes mic input volume to a target level. Whispers become audible, * shouts don't clip. Adapts to varying distance from microphone. * * ## Algorithm * * NOUS uses a simple peak-envelope follower: *   1. Track the peak amplitude of recent chunks (with decay) *   2. Compute gain = targetLevel / currentPeak *   3. Smooth gain changes to avoid abrupt volume jumps *   4. Apply gain to input samples, with hard limiting to prevent clipping * * ## Target Levels * *   - NORMAL: -12 dBFS peak (good for conversation) *   - LOUD: -6 dBFS peak (good for noisy environments) *   - QUIET: -18 dBFS peak (good for quiet rooms, prevents over-amplification) * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 Audio Capture Pipeline</a> */class AutomaticGainController(    /** Target peak level (0.0-1.0, where 1.0 = full scale). */    private val targetPeakLevel: Float = DEFAULT_TARGET_PEAK,    /** Maximum gain applied (to avoid amplifying silence). */    private val maxGain: Float = DEFAULT_MAX_GAIN,    /** Minimum gain applied (to avoid attenuating loud signals too much). */    private val minGain: Float = DEFAULT_MIN_GAIN,    /** Peak envelope decay rate per chunk (0.0-1.0, lower = slower decay). */    private val peakDecay: Float = DEFAULT_PEAK_DECAY,    /** Gain smoothing factor (0.0 = no smoothing, 1.0 = instant). */    private val gainSmoothing: Float = DEFAULT_GAIN_SMOOTHING,) {    /** Current peak envelope (decays over time). */    private var currentPeak: Float = 0f    /** Current smoothed gain. */    private var currentGain: Float = 1f    /** Whether this AGC has been released. */    private var released: Boolean = false    /**     * Apply gain to an audio chunk.     *     * @param chunk the input chunk     * @return a new chunk with gain applied     */    fun process(chunk: AudioChunk): AudioChunk {        check(!released) { "Cannot process after release" }        val inputSamples = chunk.samples        val outputSamples = ShortArray(inputSamples.size)        // Find peak of this chunk        var chunkPeak = 0f        for (s in inputSamples) {            val abs = if (s < 0) (-s).toFloat() else s.toFloat()            if (abs > chunkPeak) chunkPeak = abs        }        // Update peak envelope (decay slowly, attack instantly)        if (chunkPeak > currentPeak) {            currentPeak = chunkPeak        } else {            currentPeak *= peakDecay        }        // Compute target gain        val normalizedPeak = currentPeak / Short.MAX_VALUE        val targetGain = if (normalizedPeak > 1e-6f) {            (targetPeakLevel / normalizedPeak).coerceIn(minGain, maxGain)        } else {            maxGain // silence — apply max gain (won't matter, signal is silent)        }        // Smooth gain over time        currentGain = (currentGain * (1f - gainSmoothing)) + (targetGain * gainSmoothing)        // Apply gain with hard limiting (soft clip)        for (i in inputSamples.indices) {            val amplified = inputSamples[i].toFloat() * currentGain            // Hard limit to short range (clipping protection)            val clamped = amplified.toInt()                .coerceIn(Short.MIN_VALUE.toInt(), Short.MAX_VALUE.toInt())                .toShort()            outputSamples[i] = clamped        }        return chunk.withSamples(outputSamples)    }    /** Current gain being applied (for diagnostics). */    fun getCurrentGain(): Float = currentGain    /** Current peak envelope (for diagnostics). */    fun getCurrentPeak(): Float = currentPeak    /** Reset state. */    fun reset() {        currentPeak = 0f        currentGain = 1f    }    /** Release resources. */    fun release() {        released = true    }    companion object {        /** Target peak level: -12 dBFS ≈ 0.25 (good for conversation). */        const val DEFAULT_TARGET_PEAK = 0.25f        /** Maximum gain: 10x (20 dB) — enough for whispers, won't blow out silence. */        const val DEFAULT_MAX_GAIN = 10f        /** Minimum gain: 0.1x (-20 dB) — attenuates very loud signals. */        const val DEFAULT_MIN_GAIN = 0.1f        /** Peak decay: 95% per chunk (slow decay, fast attack). */        const val DEFAULT_PEAK_DECAY = 0.95f        /** Gain smoothing: 10% per chunk (slow changes, no abrupt jumps). */        const val DEFAULT_GAIN_SMOOTHING = 0.1f        /** Preset: NORMAL (default, -12 dBFS). */        val NORMAL = AutomaticGainController(targetPeakLevel = 0.25f)        /** Preset: LOUD (-6 dBFS, good for noisy environments). */        val LOUD = AutomaticGainController(targetPeakLevel = 0.5f)        /** Preset: QUIET (-18 dBFS, prevents over-amplification in quiet rooms). */        val QUIET = AutomaticGainController(targetPeakLevel = 0.125f)    }    protected fun finalize() {        release()    }}